function CalendarView({ activities, month, setMonth, onSelect }) {
  const year = month.getFullYear();
  const m = month.getMonth();
  const first = new Date(year, m, 1);
  const startDay = first.getDay();
  const daysInMonth = new Date(year, m + 1, 0).getDate();
  const cells = [];
  for (let i = 0; i < startDay; i++) cells.push(null);
  for (let d = 1; d <= daysInMonth; d++) cells.push(d);

  const byDay = (d) => {
    const key = `${year}-${String(m + 1).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
    return activities.filter((a) => a.date === key);
  };

  return (
    <Card>
      <div className="flex items-center justify-between mb-3">
        <button onClick={() => setMonth(new Date(year, m - 1, 1))}><ChevronLeft size={18} color={BLUE} /></button>
        <p className="font-bold text-sm capitalize">{month.toLocaleDateString("pt-BR", { month: "long", year: "numeric" })}</p>
        <button onClick={() => setMonth(new Date(year, m + 1, 1))}><ChevronRight size={18} color={BLUE} /></button>
      </div>
      <div className="grid grid-cols-7 gap-1 text-center text-[10px] text-gray-400 mb-1">
        {["D", "S", "T", "Q", "Q", "S", "S"].map((d, i) => <span key={i}>{d}</span>)}
      </div>
      <div className="grid grid-cols-7 gap-1">
        {cells.map((d, idx) => {
          if (!d) return <div key={idx} />;
          const items = byDay(d);
          return (
            <div key={idx} className="aspect-square rounded-lg p-0.5 flex flex-col items-center" style={{ background: items.length ? BLUE_BG : "transparent" }}>
              <span className="text-[10px] text-gray-500">{d}</span>
              {items.slice(0, 1).map((a) => (
                <button key={a.id} onClick={() => onSelect(a)} className="w-full h-6 rounded overflow-hidden mt-0.5">
                  {a.cover ? <img src={a.cover} className="w-full h-full object-cover" onError={(e) => (e.target.style.display = "none")} /> : <div className="w-full h-full rounded" style={{ background: BLUE_LIGHT, opacity: 0.6 }} />}
                </button>
              ))}
              {items.length > 1 && <span className="text-[9px] text-gray-400">+{items.length - 1}</span>}
            </div>
          );
        })}
      </div>
    </Card>
  );
}

