function defaultFinancialSettings() {
  return {
    marketingPercent: 10,
    pin: DEFAULT_PIN,
    fixedCategories: DEFAULT_FIXED_CATS.map((c) => ({ id: uid(), name: c.name })),
    variableCategories: DEFAULT_VARIABLE_CATS.map((c) => ({ id: uid(), name: c.name })),
  };
}

function emptyMonth(fixedCats, variableCats) {
  const fixedCosts = {};
  (fixedCats || []).forEach((c) => { fixedCosts[c.id] = { amount: 0, description: "" }; });
  const variableCosts = {};
  (variableCats || []).forEach((c) => { variableCosts[c.id] = { amount: 0, description: "" }; });
  return {
    systemValue: 0, cashValue: 0,
    fixedCosts, variableCosts,
    barberPayments: { pedro: 0, pablo: 0 },
    investments: { capacitacao: 0, espaco: 0, reserva: 0 },
    subscribers: 0,
  };
}

function monthDataFor(months, ym, fixedCats, variableCats) {
  if (months[ym]) {
    const base = emptyMonth(fixedCats, variableCats);
    return {
      ...base,
      ...months[ym],
      fixedCosts: { ...base.fixedCosts, ...(months[ym].fixedCosts || {}) },
      variableCosts: { ...base.variableCosts, ...(months[ym].variableCosts || {}) },
      barberPayments: { ...base.barberPayments, ...(months[ym].barberPayments || {}) },
      investments: { ...base.investments, ...(months[ym].investments || {}) },
    };
  }
  const priorKeys = Object.keys(months).filter((k) => k < ym).sort();
  const priorKey = priorKeys[priorKeys.length - 1];
  const base = emptyMonth(fixedCats, variableCats);
  if (priorKey && months[priorKey].fixedCosts) {
    (fixedCats || []).forEach((c) => {
      if (months[priorKey].fixedCosts[c.id]) {
        base.fixedCosts[c.id] = { ...months[priorKey].fixedCosts[c.id] };
      }
    });
  }
  return base;
}

function sumEntries(obj) {
  return Object.values(obj || {}).reduce((s, v) => s + (Number(v && v.amount) || 0), 0);
}

function computeMonth(data, marketingPercent) {
  const revenue = Number(data.cashValue) || Number(data.systemValue) || 0;
  const fixedTotal = sumEntries(data.fixedCosts);
  const variableTotal = sumEntries(data.variableCosts);
  const barberTotal = Object.values(data.barberPayments || {}).reduce((s, v) => s + (Number(v) || 0), 0);
  const otherInvestments = Object.values(data.investments || {}).reduce((s, v) => s + (Number(v) || 0), 0);
  const lucroDisponivel = revenue - fixedTotal - variableTotal - barberTotal - otherInvestments;
  const valorMarketing = lucroDisponivel * (marketingPercent / 100);
  const valorRestante = lucroDisponivel - valorMarketing;
  const caio = valorRestante * 0.85;
  const rafael = valorRestante * 0.15;
  return { revenue, fixedTotal, variableTotal, barberTotal, otherInvestments, lucroDisponivel, valorMarketing, valorRestante, caio, rafael };
}

