function BarberProfile({ barber, months, pct, onBack }) {
  const sortedMonths = Object.keys(months).sort();
  const history = sortedMonths.map((k) => {
    const data = months[k];
    const calc = computeMonth(data, pct);
    const value = barber.commission ? Number((data.barberPayments || {})[barber.id]) || 0 : Math.round(calc[barber.id]);
    return { month: monthLabel(k), value };
  });
  const total = history.reduce((s, h) => s + h.value, 0);

  return (
    <div className="space-y-4">
      <button onClick={onBack} className="flex items-center gap-1 text-sm font-semibold" style={{ color: BLUE }}>
        <ChevronLeft size={16} /> Voltar
      </button>
      <Card>
        <div className="flex items-center gap-3">
          <div className="w-12 h-12 rounded-full flex items-center justify-center text-white font-bold" style={{ background: BLUE }}>
            {barber.name[0]}
          </div>
          <div>
            <p className="font-bold">{barber.name}</p>
            <p className="text-xs text-gray-400">{barber.role}{!barber.commission && ` · participação de ${Math.round(barber.split * 100)}% no lucro`}</p>
          </div>
        </div>
        <p className="text-2xl font-extrabold mt-3" style={{ color: BLUE }}>{currency(total)}</p>
        <p className="text-xs text-gray-400">Total histórico recebido</p>
      </Card>
      {history.length > 0 ? (
        <Card>
          <p className="font-bold text-sm mb-2">Histórico mensal</p>
          <ResponsiveContainer width="100%" height={200}>
            <BarChart data={history}>
              <CartesianGrid strokeDasharray="3 3" stroke="#F1F5F9" />
              <XAxis dataKey="month" tick={{ fontSize: 11 }} />
              <YAxis tick={{ fontSize: 11 }} />
              <Tooltip formatter={(v) => currency(v)} />
              <Bar dataKey="value" fill={BLUE_LIGHT} radius={[6, 6, 0, 0]} />
            </BarChart>
          </ResponsiveContainer>
        </Card>
      ) : <EmptyState text="Nenhum lançamento financeiro ainda." />}
    </div>
  );
}


