function CalendarGrid({ events, members, month, setMonth, onSelectDay, onSelectEvent, big }) {
  const year = month.getFullYear();
  const m = month.getMonth();
  const first = new Date(year, m, 1);
  const startDay = first.getDay();
  const daysInMonth = new Date(year, m + 1, 0).getDate();
  const cells = [];
  for (let i = 0; i < startDay; i++) cells.push(null);
  for (let d = 1; d <= daysInMonth; d++) cells.push(d);

  function keyFor(d) {
    return `${year}-${String(m + 1).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
  }
  function eventsFor(d) {
    return events.filter((e) => e.date === keyFor(d));
  }
  function memberFor(id) {
    return members.find((mm) => mm.id === id);
  }

  return (
    <Card>
      <div className="flex items-center justify-between mb-3">
        <button onClick={() => setMonth(new Date(year, m - 1, 1))}><ChevronLeft size={big ? 26 : 18} color={BLUE} /></button>
        <p className={big ? "font-bold text-xl capitalize" : "font-bold text-sm capitalize"}>{month.toLocaleDateString("pt-BR", { month: "long", year: "numeric" })}</p>
        <button onClick={() => setMonth(new Date(year, m + 1, 1))}><ChevronRight size={big ? 26 : 18} color={BLUE} /></button>
      </div>
      <div className={`grid grid-cols-7 gap-1 text-center ${big ? "text-sm" : "text-[10px]"} text-gray-400 mb-1`}>
        {["D", "S", "T", "Q", "Q", "S", "S"].map((d, i) => <span key={i}>{d}</span>)}
      </div>
      <div className="grid grid-cols-7 gap-1">
        {cells.map((d, idx) => {
          if (!d) return <div key={idx} />;
          const items = d ? eventsFor(d) : [];
          return (
            <button
              key={idx}
              onClick={() => (items.length ? onSelectEvent(items[0]) : onSelectDay(keyFor(d)))}
              className={`${big ? "aspect-square" : "aspect-square"} rounded-lg p-0.5 flex flex-col items-center justify-start`}
              style={{ background: items.length ? BLUE_BG : "transparent" }}
            >
              <span className={big ? "text-sm text-gray-600" : "text-[10px] text-gray-500"}>{d}</span>
              <div className="flex flex-wrap gap-0.5 justify-center mt-0.5">
                {items.slice(0, big ? 3 : 2).map((e) => {
                  const type = SCHEDULE_TYPES.find((t) => t.id === e.type);
                  const mem = e.type === "folga" ? memberFor(e.memberId) : null;
                  if (mem && mem.photo) {
                    return <img key={e.id} src={mem.photo} className={big ? "w-6 h-6 rounded-full object-cover" : "w-3.5 h-3.5 rounded-full object-cover"} />;
                  }
                  return <span key={e.id} className={big ? "w-3 h-3 rounded-full inline-block" : "w-1.5 h-1.5 rounded-full inline-block"} style={{ background: type?.color || BLUE_LIGHT }} />;
                })}
                {items.length > (big ? 3 : 2) && <span className="text-[9px] text-gray-400">+{items.length - (big ? 3 : 2)}</span>}
              </div>
            </button>
          );
        })}
      </div>
    </Card>
  );
}

